        PaintKind::Linear => {
            let dx = paint.coordinates[2] - paint.coordinates[0];
            let dy = paint.coordinates[3] - paint.coordinates[1];
            let len = dx * dx + dy * dy;
            if len == 0.0 { 1.0 } else { ((gx - paint.coordinates[0]) * dx + (gy - paint.coordinates[1]) * dy) / len }
