fn radial_t(paint: &Paint, gx: f64, gy: f64) -> f64 {
    let (cx,cy,r,fx,fy) = (paint.coordinates[0],paint.coordinates[1],paint.coordinates[2],paint.coordinates[3],paint.coordinates[4]);
